import os
import pandas as pd
import matplotlib.pyplot as plt

def main():
    print("--- Part 2: Visualizations ---")

    # Load cleaned data generated by clean_and_eda.py
    if not os.path.exists('data/cleaned_orders.csv'):
        print("Error: data/cleaned_orders.csv not found. Please run clean_and_eda.py first.")
        return

    df = pd.read_csv('data/cleaned_orders.csv')

    # Create directory if it doesn't exist
    os.makedirs('visualizations', exist_ok=True)

    # 1. Return Rate by Payment Bar Chart
    return_stats = df.groupby('payment_method')['returned'].mean() * 100
    return_stats = return_stats.sort_values(ascending=False)

    plt.figure(figsize=(8, 5))
    ax = return_stats.plot(kind='bar', color=['#E3A33B', '#2E6B4F', '#2B7A8C'])
    plt.title('COD Returns at 44.4% — 3x Card', fontsize=14, fontweight='bold', pad=15)
    plt.xlabel('Payment Method', fontsize=12)
    plt.ylabel('Return Rate (%)', fontsize=12)
    plt.xticks(rotation=0)
    plt.ylim(0, 50)

    # Add exact percentage labels on bars
    for i, v in enumerate(return_stats):
        ax.text(i, v + 1, f"{v:.1f}%", ha='center', fontweight='bold')

    plt.tight_layout()
    plt.savefig('visualizations/return_rate_by_payment.png', dpi=300)
    plt.close()
    print("Saved: visualizations/return_rate_by_payment.png")

    # 2. Outlier-Corrected Monthly Revenue Line Chart
    df_no_outliers = df[~df['is_outlier']].copy()
    df_no_outliers['year_month'] = pd.to_datetime(df_no_outliers['order_date']).dt.strftime('%Y-%m')
    monthly_rev = df_no_outliers.groupby('year_month')['order_value'].sum()

    plt.figure(figsize=(10, 5))

    # Plot strictly using integer positions to prevent layout engine crashes
    x_positions = range(len(monthly_rev))
    plt.plot(x_positions, monthly_rev.values, marker='o', color='#2B7A8C', linewidth=2, markersize=8)
    plt.xticks(x_positions, monthly_rev.index)

    plt.title('Outlier-Corrected Revenue Trend (True Peak: March 2026)', fontsize=14, fontweight='bold', pad=15)
    plt.xlabel('Month', fontsize=12)
    plt.ylabel('Revenue (INR)', fontsize=12)
    plt.grid(True, linestyle='--', alpha=0.6)

    # Annotate peak using the exact integer position mapping
    peak_month = monthly_rev.idxmax()
    peak_val = monthly_rev.max()
    peak_idx = monthly_rev.index.get_loc(peak_month)

    plt.annotate(f"Peak: ₹{peak_val:,.2f}",
                 xy=(peak_idx, peak_val),
                 xytext=(0, 10),
                 textcoords="offset points",
                 ha='center', fontweight='bold', color='#17402F')

    plt.tight_layout()
    plt.savefig('visualizations/monthly_revenue_trend.png', dpi=300)
    plt.close()
    print("Saved: visualizations/monthly_revenue_trend.png")

if __name__ == '__main__':
    main()
